package com.fittrack.auth; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.http.*; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.core.context.SecurityContextHolder; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; @Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean org.springframework.web.cors.CorsConfigurationSource corsConfigurationSource(){var c=new org.springframework.web.cors.CorsConfiguration();c.setAllowedOrigins(java.util.List.of("http://localhost:5173","http://localhost:3000"));c.setAllowedMethods(java.util.List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Authorization","Content-Type"));c.setAllowCredentials(true);var source=new org.springframework.web.cors.UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",c);return source;} @Bean SecurityFilterChain chain(HttpSecurity h, JwtService j)throws Exception{return h.cors(c->c.configurationSource(corsConfigurationSource())).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**","/actuator/health","/api/v1/health").permitAll().anyRequest().authenticated()).addFilterBefore(new Filter(){public void doFilter(ServletRequest req,ServletResponse res,FilterChain c)throws IOException,ServletException{doFilterInternal((HttpServletRequest)req,(HttpServletResponse)res,c);} public void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{j.subject(h.substring(7)); var auth=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(j.subject(h.substring(7)),null,java.util.List.of());SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}c.doFilter(r,s);}},UsernamePasswordAuthenticationFilter.class).build();} }
